<template>
  <div class="segment-editor" v-loading="uploading">
    <el-tabs v-model="section" class="segment-tabs"><el-tab-pane label="01 剧本与规格" name="script" /><el-tab-pane label="02 角色与场景" name="assets" /><el-tab-pane label="03 导演与提示词" name="direction" /><el-tab-pane label="04 画面与参考" name="media" /></el-tabs>
    <div class="segment-content">
      <div class="segment-main">
        <section v-show="section === 'script'" class="form-stack">
          <div v-if="index > 0" class="segment-continuity"><el-checkbox :model-value="!segment.continuityOverride" @update:model-value="setInherit(!!$event)">继承全局接续方式</el-checkbox><ContinuationModeSelector v-if="segment.continuityOverride" v-model="segment.continuityOverride" compact :overlap-frames="range?.overlapFrames" :capabilities="continuationModes" :anchor-segments="anchorSegments" /><p v-else class="helper">本接续点使用全局设置；关闭继承可单独调整。</p></div>
          <label>片段名称<el-input v-model="segment.name" placeholder="为本段命名" /></label>
          <div class="grid grid-cols-2 gap-4"><label>景别<DictSelect v-model="segment.shotType" dict-type="shot_type" placeholder="AUTO · 自动规划" /><el-checkbox v-model="segment.shotTypeLocked" :disabled="!segment.shotType || segment.shotType === 'AUTO'">明确锁定景别</el-checkbox></label><label>运镜<DictSelect v-model="segment.cameraMovement" dict-type="camera_movement" placeholder="AUTO · 自动规划" /><el-checkbox v-model="segment.cameraMovementLocked" :disabled="!segment.cameraMovement || segment.cameraMovement === 'AUTO'">明确锁定运镜</el-checkbox></label></div>
          <label>本段剧本<el-input v-model="segment.scriptContent" type="textarea" :rows="7" placeholder="本段发生的动作、情绪、对白与叙事内容" /></label>
          <div class="grid grid-cols-2 gap-4"><label>画面动作<el-input v-model="segment.actionDescription" type="textarea" :rows="3" /></label><label>声音与环境<el-input v-model="segment.soundEffect" type="textarea" :rows="3" /></label></div>
          <div class="range-card"><div><small>生成范围</small><strong>{{ seconds(segment.startFrame) }}–{{ seconds(segment.endFrame) }} 秒</strong></div><div><small>成片保留</small><strong>{{ seconds(range?.keepStartFrame ?? segment.startFrame) }}–{{ seconds(range?.keepEndFrame ?? segment.endFrame) }} 秒</strong></div><div><small>共享上下文</small><strong>{{ index ? `来自片段 ${String(index).padStart(2, '0')} · ${range?.overlapFrames ?? 0} 帧` : '首段 · 无前序片段' }}</strong></div></div>
          <el-collapse><el-collapse-item title="手动微调生成范围" name="range"><div class="grid grid-cols-2 gap-3"><label>起始帧<el-input-number v-model="segment.startFrame" :min="0" :step="17" /></label><label>结束帧<el-input-number v-model="segment.endFrame" :min="22" :step="17" /></label></div><p class="helper">修改后重新校验整条时间轴；片段须有真实重叠。</p></el-collapse-item></el-collapse>
          <div class="context-note">{{ index ? '生成时使用上一段的实际尾部作为引导；上一段生成后才有真实画面。' : '首段使用你明确挂载的画面与参考素材。' }}</div>
        </section>
        <section v-show="section === 'assets'" class="form-stack">
          <div class="section-title"><h3>本段角色与造型</h3><div class="flex gap-2"><el-select v-model="newCharacter" filterable placeholder="选择角色" class="!w-48"><el-option v-for="c in characters" :key="String(c.id)" :value="String(c.id)" :label="c.name" /></el-select><el-button :disabled="!newCharacter" @click="addCharacter">添加</el-button></div></div>
          <div v-for="(c, i) in segment.characterRefs" :key="String(c.characterId)" class="asset-card"><div class="section-title"><strong>{{ character(c.characterId)?.name || c.characterName || c.characterId }}</strong><el-button text size="small" type="danger" @click="segment.characterRefs?.splice(i, 1)">移除</el-button></div><label>本段造型<el-select v-model="c.lookId" clearable placeholder="不指定独立造型"><el-option v-for="look in character(c.characterId)?.looks || []" :key="String(look.id)" :value="String(look.id)" :label="look.lookName" /></el-select></label><div class="grid grid-cols-2 gap-3"><label>动作<el-input v-model="c.actionPrompt" /></label><label>表情<el-input v-model="c.emotionPrompt" /></label></div><label>站位与构图<el-input v-model="c.positionTag" /></label><el-button size="small" :disabled="generationMode !== 'REFERENCE_MODE' || !characterImage(c)" @click="mountCharacter(c)">将形象图挂载到本段参考</el-button></div>
          <p v-if="!segment.characterRefs?.length" class="helper">本段还未选择角色；角色绑定不会自动分配到其他片段。</p>
          <div class="section-title"><h3>场景与背景</h3></div><label>本段场景<el-select v-model="segment.resSceneId" clearable filterable placeholder="选择场景" @change="segment.resKeyframeId = undefined"><el-option v-for="s in scenes" :key="String(s.id)" :value="String(s.id)" :label="s.name" /></el-select></label>
          <label>场景描述覆盖<el-input v-model="segment.customScenePrompt" type="textarea" :rows="3" placeholder="仅覆盖本段场景描述" /></label><el-button v-if="selectedScene" size="small" :disabled="generationMode !== 'REFERENCE_MODE' || !(selectedScene.referenceImageUrl || selectedScene.coverUrl)" @click="mountImage(selectedScene.referenceImageUrl || selectedScene.coverUrl, selectedScene.name, 'SCENE')">将场景图挂载到本段参考</el-button>
          <label>关键帧背景<el-select v-model="segment.resKeyframeId" clearable filterable placeholder="可选，与场景互斥" @change="segment.resSceneId = undefined"><el-option v-for="k in keyframes" :key="String(k.id)" :value="String(k.id)" :label="k.name" /></el-select></label>
          <div class="section-title"><h3>本段道具</h3><div class="flex gap-2"><el-select v-model="newProp" filterable placeholder="选择道具" class="!w-48"><el-option v-for="p in propsOptions" :key="String(p.id)" :value="String(p.id)" :label="p.name" /></el-select><el-button :disabled="!newProp" @click="addProp">添加</el-button></div></div>
          <div v-for="(p, i) in segment.propRefs" :key="String(p.propId)" class="asset-card"><div class="section-title"><strong>{{ p.propName || p.propId }}</strong><el-button text type="danger" size="small" @click="segment.propRefs?.splice(i, 1)">移除</el-button></div><label>本段道具描述<el-input v-model="p.propPrompt" type="textarea" :rows="2" /></label></div>
        </section>
        <section v-show="section === 'direction'" class="form-stack">
          <ContinuationDirectorEditor v-model="segment.directorPlan" :duration="duration" />
          <label>视频提示词<el-input v-model="segment.prompt" type="textarea" :rows="7" placeholder="本段英文视频提示词；引用编号仅对应本段素材" /></label>
          <div class="grid grid-cols-2 gap-4"><label>首帧生图提示词<el-input v-model="segment.firstFramePrompt" type="textarea" :rows="5" /></label><label>尾帧生图提示词<el-input v-model="segment.endFramePrompt" type="textarea" :rows="5" /></label></div>
          <label>负向提示词<el-input v-model="segment.negativePrompt" type="textarea" :rows="3" /></label>
          <el-button @click="emit('plan')">AI 规划本段内容与提示词</el-button>
        </section>
        <section v-show="section === 'media'" class="form-stack">
          <template v-if="generationMode === 'FIRST_LAST_FRAME'"><div class="grid grid-cols-2 gap-4"><div v-for="kind in (['first','last'] as const)" :key="kind" class="asset-card"><h3>{{ kind === 'first' ? '首帧' : '尾帧' }}（可选）</h3><el-image v-if="kind === 'first' ? segment.firstFrameImageUrl : segment.lastFrameImageUrl" :src="kind === 'first' ? segment.firstFrameImageUrl : segment.lastFrameImageUrl" class="anchor-image" fit="contain" /><div v-else class="media-placeholder">未设置画面</div><el-upload :show-file-list="false" accept="image/*" :before-upload="(file: File) => upload(file, kind)"><el-button size="small">上传{{ kind === 'first' ? '首帧' : '尾帧' }}</el-button></el-upload><el-button size="small" text @click="kind === 'first' ? segment.firstFrameImageUrl = undefined : segment.lastFrameImageUrl = undefined">清空</el-button></div></div><p class="helper">从主控素材池可将已有图片明确挂载为本段首帧或尾帧。</p><el-button v-if="segment.referenceImages.length || segment.referenceVideos.length || segment.referenceAudios?.length" type="danger" plain @click="clearReferenceModeMedia">清空本段普通参考素材</el-button></template>
          <template v-else>
            <div class="section-title"><h3>参考图 <span>{{ segment.referenceImages.length }} / 9</span></h3><div class="flex gap-2"><el-button size="small" @click="chooseAssets">从资产库选择</el-button><el-upload :show-file-list="false" accept="image/*" :before-upload="(file: File) => upload(file, 'image')"><el-button size="small">上传参考图</el-button></el-upload></div></div>
            <div class="image-grid"><div v-for="(img, i) in segment.referenceImages" :key="img.id" class="image-tile"><el-image :src="img.imageUrl" fit="cover" :preview-src-list="[img.imageUrl]" preview-teleported /><el-select v-model="img.usageRole" placeholder="选择图片用途" size="small"><el-option v-for="option in referenceImageUsageOptions(img.sourceType)" :key="option.value" :value="option.value" :label="option.label" /></el-select><div>Picture {{ i + 1 }}<el-button size="small" text type="danger" @click="segment.referenceImages.splice(i, 1)">移除</el-button></div></div><div v-if="!segment.referenceImages.length" class="media-placeholder">只使用明确挂载到本段的图片</div></div>
            <div class="section-title"><h3>参考视频 <span>{{ segment.referenceVideos.length }} / 3</span></h3><div class="flex gap-2"><el-upload :show-file-list="false" accept="video/*" :before-upload="(file: File) => upload(file, 'video')"><el-button size="small">上传本段视频</el-button></el-upload><el-button size="small" @click="videoPicker?.open()">选择分镜 / Take</el-button></div></div>
            <div v-for="(v, i) in segment.referenceVideos" :key="v.id" class="asset-card"><div class="section-title"><strong>Video {{ i + 1 }} · {{ v.name || '参考视频' }}</strong><el-button size="small" text type="danger" @click="removeVideo(i)">移除</el-button></div><div class="grid grid-cols-2 gap-3"><label>源起点（秒）<el-input-number v-model="v.startSeconds" :min="0" :step="0.5" @change="clearFrameRange(v)" /></label><label>源终点（秒）<el-input-number v-model="v.endSeconds" :min="0.1" :step="0.5" @change="clearFrameRange(v)" /></label></div><div class="flex items-center gap-3"><el-tag v-if="v.sourceStartFrame !== undefined" size="small">按计划精确切帧</el-tag><el-checkbox v-model="v.includeAudio">参考原音</el-checkbox></div></div>
            <ShotControlNetEditor v-model="control" :videos="segment.referenceVideos" />
            <div class="section-title"><h3>参考音频 <span>{{ segment.referenceAudios?.length || 0 }} / 3</span></h3><el-button size="small" @click="audioVisible = true">从音频库选择</el-button></div><div v-for="(a, i) in segment.referenceAudios" :key="a.id || a.audioUrl" class="asset-card"><div class="section-title"><strong>Audio {{ i + 1 }} · {{ a.name || '音频' }}</strong><el-button text size="small" type="danger" @click="segment.referenceAudios?.splice(i, 1)">移除</el-button></div><audio :src="a.audioUrl" controls class="w-full" /><label>参考关系<el-select v-model="a.referenceType"><el-option v-for="v in REFERENCE_AUDIO_TYPE_OPTIONS" :key="v.value" :value="v.value" :label="v.label" /></el-select></label></div>
          </template>
        </section>
      </div>
      <aside class="segment-summary"><small>本段内容</small><button @click="section = 'assets'">角色 <b>{{ segment.characterRefs?.length || 0 }}</b><span>02 →</span></button><button @click="section = 'assets'">场景 <b>{{ segment.resSceneId || segment.resKeyframeId ? 1 : 0 }}</b><span>02 →</span></button><button @click="section = 'direction'">导演规划 <b>{{ segment.directorPlan ? '已配置' : '未配置' }}</b><span>03 →</span></button><button @click="section = 'media'">参考图 <b>{{ segment.referenceImages.length }}</b><span>04 →</span></button><button @click="section = 'media'">参考视频 <b>{{ segment.referenceVideos.length }}</b><span>04 →</span></button><button @click="section = 'media'">ControlNet <b>{{ segment.controlNetEnabled ? '开启' : '关闭' }}</b><span>04 →</span></button></aside>
    </div>
    <AssetMultiSelectDialog ref="assetPicker" @confirm="mountAssets" />
    <ShotVideoPickerDialog ref="videoPicker" @selected="selectedVideo" />
    <VoiceAudioPicker v-model="audioVisible" :shot-id="shotId" :drama-id="dramaId" :characters="characters" :max-audios="3" :selected-audios="segment.referenceAudios || []" @select="values => segment.referenceAudios?.push(...values)" />
  </div>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { ElMessage } from 'element-plus'
import DictSelect from '@/components/DictSelect.vue'
import ContinuationDirectorEditor from './ContinuationDirectorEditor.vue'
import ShotControlNetEditor from './ShotControlNetEditor.vue'
import AssetMultiSelectDialog, { type AssetSelectItem } from './AssetMultiSelectDialog.vue'
import ShotVideoPickerDialog from '@/views/production/components/ShotVideoPickerDialog.vue'
import VoiceAudioPicker from '@/views/assets/components/AudioReferencePicker.vue'
import { assetApi } from '@/api/res-asset'
import { shotVideoReferenceApi } from '@/api/shot-video-reference'
import { REFERENCE_AUDIO_TYPE_OPTIONS, referenceImageUsageOptions } from '@/constants/referenceMediaOptions'
import ContinuationModeSelector from './ContinuationModeSelector.vue'
import type { ContinuationSegment, ContinuationPlan, ContinuityOptions, ContinuityMode, ContinuityCapability } from '@/types/continuation'
import type { CharacterShotRefInfo, ShotRefImage, ShotRefVideo } from '@/types/drama'
import type { ResCharacterOption, ResSceneOption, ResPropOption } from '@/types/resource'
const props = defineProps<{ segment: ContinuationSegment; index: number; continuity?: ContinuityOptions; continuationModes?: Partial<Record<ContinuityMode, ContinuityCapability>>; anchorSegments?: ContinuationSegment[]; range?: ContinuationPlan['ranges'][number]; generationMode: string; shotId: string; dramaId?: string | number; characters: ResCharacterOption[]; scenes: ResSceneOption[]; propsOptions: ResPropOption[]; keyframes: Array<{ id: string | number; name: string }>; activeSection: string }>()
const emit = defineEmits<{ 'update:activeSection': [value: string]; plan: [] }>()
const section = computed({ get: () => props.activeSection, set: value => emit('update:activeSection', value) })
function setInherit(inherit: boolean) { props.segment.continuityOverride = inherit ? null : JSON.parse(JSON.stringify(props.continuity || { mode: 'GUIDE' })) }
const duration = computed(() => Math.round((props.segment.endFrame - props.segment.startFrame) / 24 * 1000) / 1000)
const selectedScene = computed(() => props.scenes.find(s => String(s.id) === String(props.segment.resSceneId)))
const newCharacter = ref(''), newProp = ref(''), uploading = ref(false), audioVisible = ref(false)
const assetPicker = ref<InstanceType<typeof AssetMultiSelectDialog>>(), videoPicker = ref<InstanceType<typeof ShotVideoPickerDialog>>()
let alive = true
onBeforeUnmount(() => { alive = false })
const seconds = (frames: number) => (frames / 24).toFixed(2)
const character = (id?: string | number) => props.characters.find(c => String(c.id) === String(id))
function addCharacter() { if (!props.segment.characterRefs?.some(c => String(c.characterId) === newCharacter.value)) props.segment.characterRefs?.push({ characterId: newCharacter.value }); newCharacter.value = '' }
function addProp() { const p = props.propsOptions.find(p => String(p.id) === newProp.value); if (p && !props.segment.propRefs?.some(r => String(r.propId) === String(p.id))) props.segment.propRefs?.push({ propId: String(p.id), propName: p.name, propType: p.propType, propPrompt: p.propPrompt }); newProp.value = '' }
function characterImage(c: CharacterShotRefInfo) { const option = character(c.characterId); return c.lookId ? option?.looks?.find(l => String(l.id) === String(c.lookId))?.referenceImageUrl : option?.referenceImageUrl || option?.avatarUrl }
function mountCharacter(c: CharacterShotRefInfo) { mountImage(characterImage(c), character(c.characterId)?.name || '角色形象', 'CHARACTER_REFERENCE') }
function mountImage(url: string | undefined, name: string, sourceType: ShotRefImage['sourceType'] = 'UPLOAD') { if (!url) return; if (props.segment.referenceImages.length >= 9) return ElMessage.warning('本段参考图最多9张'); props.segment.referenceImages.push({ id: crypto.randomUUID(), sourceType, imageUrl: url, name, bindingMode: 'SNAPSHOT' }) }
function chooseAssets() { assetPicker.value?.open({ dramaId: props.dramaId, maxSelectable: 9 - props.segment.referenceImages.length, alreadySelectedUrls: props.segment.referenceImages.map(i => i.imageUrl), title: '选择本段参考资产' }) }
function mountAssets(items: AssetSelectItem[]) { for (const item of items) mountImage(item.imageUrl, item.name, item.sourceType) }
const control = computed({ get: () => ({ enabled: props.segment.controlNetEnabled, referenceId: props.segment.controlVideoId, controlType: props.segment.controlType, strength: props.segment.controlStrength }), set: value => { props.segment.controlNetEnabled = value.enabled; props.segment.controlVideoId = value.referenceId; props.segment.controlType = value.controlType as ContinuationSegment['controlType']; props.segment.controlStrength = value.strength } })
function clearFrameRange(v: ShotRefVideo) { delete v.sourceStartFrame; delete v.sourceEndFrame }
function removeVideo(index: number) { const value = props.segment.referenceVideos.splice(index, 1)[0]; if (value?.id === props.segment.controlVideoId) props.segment.controlVideoId = undefined; if (!props.segment.referenceVideos.length) props.segment.controlNetEnabled = false }
function clearReferenceModeMedia() { props.segment.referenceImages = []; props.segment.referenceVideos = []; props.segment.referenceAudios = []; props.segment.controlNetEnabled = false }
async function addVideo(value: ShotRefVideo) { if (props.segment.referenceVideos.length >= 3) throw new Error('本段参考视频最多3段'); const probe = await shotVideoReferenceApi.probe(props.shotId, value); if (alive) props.segment.referenceVideos.push({ ...value, endSeconds: Math.min(probe.duration || duration.value, duration.value) }) }
async function upload(file: File, kind: 'image' | 'first' | 'last' | 'video') { uploading.value = true; try { const result = await assetApi.upload(file, 'continuation'); if (!alive) return false; if (kind === 'video') await addVideo({ id: crypto.randomUUID(), sourceType: 'DIRECT_URL', sourceVideoUrl: result.url, startSeconds: 0, includeAudio: false, name: file.name }); else if (kind === 'first') props.segment.firstFrameImageUrl = result.url; else if (kind === 'last') props.segment.lastFrameImageUrl = result.url; else mountImage(result.url, file.name) } catch (e: any) { ElMessage.error(e.message || '上传失败') } finally { uploading.value = false } return false }
async function selectedVideo(value: { sourceType: ShotRefVideo['sourceType']; sourceVideoUrl: string; sourceShotId?: string; sourceVideoTakeId?: string; shotName?: string }) { uploading.value = true; try { await addVideo({ id: crypto.randomUUID(), name: value.shotName, sourceType: value.sourceType, sourceVideoUrl: value.sourceType === 'DIRECT_URL' ? value.sourceVideoUrl : undefined, sourceShotId: value.sourceShotId, sourceVideoTakeId: value.sourceVideoTakeId, startSeconds: 0, includeAudio: false }) } catch (e: any) { ElMessage.error(e.message || '挂载视频失败') } finally { uploading.value = false } }
defineExpose({ focusSection: (value: string) => { section.value = value } })
</script>

<style scoped>
.segment-tabs{padding:0 20px;border-bottom:1px solid var(--border-default,#e7e7ef)}.segment-tabs :deep(.el-tabs__header){margin:0}.segment-content{display:grid;grid-template-columns:minmax(0,1fr) 180px;gap:24px;padding:24px}.form-stack{display:grid;gap:20px}label{display:grid;gap:7px;font-size:12px;color:var(--text-secondary)}h3{font-size:14px;font-weight:650;margin:0}h3 span{font-size:11px;font-weight:400;color:var(--text-muted)}.section-title{display:flex;justify-content:space-between;align-items:center;gap:12px}.range-card{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;border:1px solid var(--border-default);border-radius:10px;padding:16px}.range-card small{display:block;font-size:11px;color:var(--text-muted);margin-bottom:8px}.range-card strong{font-size:12px}.context-note{background:var(--brand-soft,#f6f2ff);color:var(--text-secondary);font-size:12px;border-radius:9px;padding:16px}.asset-card{border:1px solid var(--border-default,#e5e7eb);border-radius:10px;padding:14px;display:grid;gap:12px}.helper{font-size:12px;line-height:1.7;color:var(--text-muted)}.segment-summary{border-left:1px solid var(--border-default);padding-left:18px}.segment-summary small{display:block;font-size:11px;color:var(--text-muted);margin-bottom:16px}.segment-summary button{display:flex;flex-wrap:wrap;gap:8px;width:100%;border:1px solid var(--border-default);border-radius:9px;padding:12px;margin-bottom:10px;font-size:12px;text-align:left}.segment-summary button:hover{border-color:var(--brand)}.segment-summary button span{color:var(--brand);margin-left:auto;font-size:11px}.image-grid{display:flex;flex-wrap:wrap;gap:12px}.image-tile{width:130px}.image-tile>.el-image{width:130px;height:100px;border-radius:8px}.image-tile>div{display:flex;align-items:center;justify-content:space-between;font-size:11px}.media-placeholder{padding:28px;border:1px dashed var(--border-default);border-radius:8px;color:var(--text-muted);font-size:12px}.anchor-image{width:100%;height:170px;background:var(--surface-muted);border-radius:8px}.el-select,.el-input-number{width:100%}@media(max-width:1200px){.segment-content{grid-template-columns:minmax(0,1fr)}.segment-summary{display:none}}@media(max-width:750px){.segment-content{padding:14px}.grid,.range-card{grid-template-columns:1fr}.section-title{flex-wrap:wrap}}
</style>
